def teile(a, b):
    try:
        return a // b
    except ZeroDivisionError:
        return -1

print(teile(5, 0))

def setze_alter(a):
    if a < 0 or a > 150:
        raise ValueError("Alter unrealistisch")
    return a

try:
    print(f"Alter: {setze_alter(200)}")
except ValueError as e:
    print(e)

class LeerError(Exception):
    pass

try:
    raise LeerError()
except ValueError:
    print("Leer")
except Exception:
    print("Fehler")
